//! A trained ternary network (scikit-learn digits MLP, 64 -> 128 -> 10, ternary weights
//! with int8 activations, quantisation-aware trained) run through the ternary x int8 GEMM.
//!
//! Generated by `scripts/train_ternary_digits.py`; the JSON is committed so this test
//! needs no Python. It checks that every available kernel:
//!
//! * reproduces the Python integer pipeline's predictions on all held-out samples,
//! * reproduces its layer-1 `i32` accumulators exactly,
//! * reproduces its logits to float rounding.
//!
//! It also checks that the accuracy equals the recorded one. The recorded numbers
//! (f32 baseline, ternary QAT, ternary post-training quantisation) are sanity-checked
//! so a regression in the training script cannot silently weaken the claim.

use ntg_kernel::ntg::storage::{Int8Activations, PackedTernaryMatrix, TernaryI8Kernel};
use serde_json::Value;

const DATA: &str = include_str!("data/ternary_digits_mlp.json");
const INPUTS: usize = 64;
const CLASSES: usize = 10;

struct Model {
    hidden: usize,
    w1: PackedTernaryMatrix,
    w2: PackedTernaryMatrix,
    b1: Vec<f32>,
    b2: Vec<f32>,
    data: Value,
}

fn f32s(v: &Value) -> Vec<f32> {
    v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap() as f32).collect()
}

fn i8s(v: &Value) -> Vec<i8> {
    v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap() as i8).collect()
}

fn load() -> Model {
    let data: Value = serde_json::from_str(DATA).expect("valid JSON");
    let hidden = data["hidden"].as_u64().unwrap() as usize;
    let w1 = PackedTernaryMatrix::from_i8(&i8s(&data["w1"]), hidden, INPUTS)
        .unwrap()
        .with_scale(data["gamma1"].as_f64().unwrap() as f32);
    let w2 = PackedTernaryMatrix::from_i8(&i8s(&data["w2"]), CLASSES, hidden)
        .unwrap()
        .with_scale(data["gamma2"].as_f64().unwrap() as f32);
    Model { hidden, w1, w2, b1: f32s(&data["b1"]), b2: f32s(&data["b2"]), data }
}

struct Run {
    pred: Vec<usize>,
    logits: Vec<f32>,
    acc1: Vec<i32>,
}

fn run(m: &Model, kernel: TernaryI8Kernel) -> Run {
    let pixels = m.data["test_pixels"].as_array().unwrap();
    let batch = pixels.len();
    let x: Vec<f32> = pixels
        .iter()
        .flat_map(|row| row.as_array().unwrap().iter().map(|p| p.as_i64().unwrap() as f32 / 16.0))
        .collect();

    // Layer 1: int8 inputs x ternary weights, then dequantise + bias + ReLU.
    let q = Int8Activations::quantize_f32(&x, batch, INPUTS).unwrap();
    let mut acc1 = vec![0i32; batch * m.hidden];
    m.w1.gemm_i8(&q, &mut acc1, kernel).unwrap();
    let mut z1 = vec![0f32; batch * m.hidden];
    m.w1.forward_f32(&q, &mut z1, kernel).unwrap();
    for b in 0..batch {
        for n in 0..m.hidden {
            let v = z1[b * m.hidden + n] + m.b1[n];
            z1[b * m.hidden + n] = v.max(0.0);
        }
    }

    // Layer 2.
    let h = Int8Activations::quantize_f32(&z1, batch, m.hidden).unwrap();
    let mut logits = vec![0f32; batch * CLASSES];
    m.w2.forward_f32(&h, &mut logits, kernel).unwrap();
    for b in 0..batch {
        for c in 0..CLASSES {
            logits[b * CLASSES + c] += m.b2[c];
        }
    }
    let pred = (0..batch)
        .map(|b| {
            let row = &logits[b * CLASSES..(b + 1) * CLASSES];
            let mut best = 0;
            for (i, &v) in row.iter().enumerate() {
                if v > row[best] {
                    best = i;
                }
            }
            best
        })
        .collect();
    Run { pred, logits, acc1 }
}

#[test]
fn every_kernel_reproduces_the_python_integer_pipeline() {
    let m = load();
    let ref_pred: Vec<usize> =
        m.data["ref_pred"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
    let ref_logits = m.data["ref_logits_first16"].as_array().unwrap();
    let ref_acc = m.data["ref_acc1_first8"].as_array().unwrap();

    for kernel in TernaryI8Kernel::all_available() {
        let r = run(&m, kernel);
        assert_eq!(r.pred, ref_pred, "{}: predictions differ from the Python pipeline", kernel.name());

        for (b, row) in ref_acc.iter().enumerate() {
            let want: Vec<i32> = row.as_array().unwrap().iter().map(|v| v.as_i64().unwrap() as i32).collect();
            assert_eq!(
                &r.acc1[b * m.hidden..(b + 1) * m.hidden],
                &want[..],
                "{}: layer-1 accumulators differ for sample {b}",
                kernel.name()
            );
        }
        for (b, row) in ref_logits.iter().enumerate() {
            for (c, want) in f32s(row).iter().enumerate() {
                let got = r.logits[b * CLASSES + c];
                assert!(
                    (got - want).abs() < 1e-4,
                    "{}: logit [{b}][{c}] {got} vs {want}",
                    kernel.name()
                );
            }
        }
    }
}

#[test]
fn trained_accuracy_matches_the_recorded_numbers() {
    let m = load();
    let labels: Vec<usize> =
        m.data["test_labels"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
    let r = run(&m, TernaryI8Kernel::best_available());
    let correct = r.pred.iter().zip(&labels).filter(|(p, l)| p == l).count();
    let acc = correct as f64 / labels.len() as f64;

    let rec = &m.data["accuracy"];
    let qat = rec["ternary_qat_int8"].as_f64().unwrap();
    let f32_acc = rec["f32"].as_f64().unwrap();
    let ptq = rec["ternary_ptq_int8"].as_f64().unwrap();
    assert!((acc - qat).abs() < 1e-9, "Rust accuracy {acc} != recorded {qat}");

    // The claim being protected: ternary + int8 trained properly stays close to f32,
    // and skipping quantisation-aware training costs real accuracy.
    assert!(qat >= 0.93, "ternary QAT accuracy {qat} too low");
    assert!(f32_acc - qat < 0.04, "gap to f32 grew: {f32_acc} vs {qat}");
    assert!(ptq < qat, "post-training quantisation ({ptq}) should be worse than QAT ({qat})");
    assert!(m.data["ternary_zero_fraction"].as_f64().unwrap() > 0.2, "weights should be sparse-ish");
}
